    sc_pkcs15_parse_tokeninfo(ctx, tokeninfo, Data, Size);
    sc_pkcs15_free_tokeninfo(tokeninfo);

    sc_pkcs15_parse_unusedspace(Data, Size, p15card);

    return 0;
}
